"""Archive one completed balanced-head trial and its failures without promotion."""
import csv,json,shutil,sys
from datetime import datetime,timedelta,timezone
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'src'))
from smart_parking.provenance import digest
E=ROOT/'experiments/evidence/HEARTBEAT-20261026T233906Z'
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def dump(p,v):p.write_text(json.dumps(v,indent=2)+'\n',encoding='utf-8')
def append(path,title,body):
    p=ROOT/path;t=p.read_text(encoding='utf-8');assert title not in t;p.write_text(t.rstrip()+'\n\n'+title+'\n\n'+body+'\n',encoding='utf-8')

def main():
    assert not (E/'checks.json').exists();now=datetime.now(timezone.utc).isoformat();s=read(ROOT/'data/automation_state.json');r=read(ROOT/'models/acpds_balanced_head.json');out=ROOT/'experiments/results'/r['run_id'];p=read(out/'protocol.json');data=read(ROOT/'reports/acpds_training_data_latest.json');plan=read(ROOT/'data/manifests/acpds_training_acquisition_v1.json')
    assert s['completed_recorded_runs_since_schedule']==len(set(s['completed_run_ids']))==92 and not s['active_training_jobs'] and not s['active_validation_jobs'];assert digest(out/'protocol.json')==r['protocol_sha256'] and digest(ROOT/r['candidate_checkpoint'])==r['candidate_checkpoint_sha256']
    for name,h in {**p['input_hashes'],**p['source_hashes'],**p['protected_hashes'],**plan['source_hashes'],**plan['input_hashes'],**plan['protected_hashes']}.items():assert digest(ROOT/name)==h,name
    for f in r['feature_cache_files']:assert digest(ROOT/f['path'])==f['sha256']
    assert digest(ROOT/data['manifest'])==data['manifest_sha256'] and data['training_images']==231 and data['validation_images']==35 and data['completed_experiment_count_added']==0
    frozen=read(ROOT/'experiments/evidence/HEARTBEAT-20261026T230905Z/checks.json')['frozen_hashes_unchanged']
    for name,h in frozen.items():assert digest(ROOT/name)==h,name
    tests=(E/'unit_tests.txt').read_text(encoding='utf-8-sig');assert 'Ran 414 tests' in tests and tests.rstrip().endswith('OK')
    live=read(ROOT/'data/processed/singapore_prospective/summary.json');health=read(ROOT/'reports/singapore_issuance_health_latest.json');issuance=read(ROOT/'reports/singapore_issuance_latest.json');snapshots=len(list((ROOT/'data/raw/singapore_live').glob('*.json')));assert snapshots==65 and health['status']=='healthy' and not health['target_json_decoded'] and not health['performance_evaluated']
    receipts=[json.loads(line) for line in (ROOT/'data/resource_receipts.jsonl').read_text(encoding='utf-8').splitlines()];last=next(x for x in reversed(receipts) if x['source_id']=='SRC-LIVE-001');nexttime=(datetime.fromisoformat(live['checked_at'])+timedelta(minutes=30)).isoformat();s['scheduled_wakeups_completed']+=1;s['last_wakeup_completed_at']=now;s['prospective_live_summary']=live
    s['singapore_issuance_health'].update(metadata_status='healthy',status='healthy',raw_files_hashed_once=health['raw_files_hashed_once'],semantic_context_verified=False,performance_evaluated=False,forecasts_logged=health['forecasts_logged'],global_origins=health['global_origins'])
    s['acpds_complete_training_acquisition']=data;s['next_actions']=[
        'Collect once AFTER '+nexttime+' using scripts/collect_singapore_study.py;then routine check_singapore_issuance_health.py WITHOUT --record-trial. Latest65official snapshots;'+str(health['forecasts_logged'])+'genuine learnedforecasts/'+str(health['global_origins'])+'origins metadatahealthy/unscored. No backfill or retrospective issue.',
        'Completed ONE source-balanced linear-head trial '+r['run_id']+'. Source acquisition completed231TRAIN/35VALID,7842/1904spaces;all266images/layouts and receipts intact. See models/acpds_balanced_head.json and docs/ACPDS_ADAPTATION_PROTOCOL.md. Selectedepoch'+str(r['selected_epoch'])+' of'+str(r['epochs_completed'])+';development gate='+str(r['development_gate_passed'])+'. Candidate separate at'+r['candidate_checkpoint']+';original productionweights unchanged. Do not repeat optimizer/source-weight/crop/threshold grids on these validation cohorts.',
        ('If all development gates pass, next implement/test a durable canonical whole-ACPDS-TEST claim and frozen final protocol before any reserved TEST pixels/semantic labels;no automatic final invocation or app promotion. ' if r['development_gate_passed'] else 'Development readiness failed:inspect the preserved gate/identity-retention evidence and continue independent useful work (fresh region-data qualification,real traffic/application/report work). Do not open TEST or turn failed metrics into acceptance by changing thresholds/cohorts. ')+ 'All27defaultclosed images and whole publisherTEST/alllots/views/aliases remainclosed;earlier PKLot/UVG final groups stayconsumed/closed.',
        'Resumable acquisition verified38cached members and acquired228TRAIN members;295388491newnetwork bytes. Source manifest '+data['manifest']+' sha256='+data['manifest_sha256']+'. Feature caches from this trial permit exact archived analysis;do not call an identical replay a new run. Ten new receipt/identity fixtures bring fullsuite414passingtests;retention follows same baseline space IDs,not replacement counts.',
        'SG final CLOSED until2026-10-27T10:51UTC(16:21IST). No interim learned target/matching/error/coverage decoding,refit,backdating/backfill. Existing once-only scorer/globalclaim atclosure. Rollingpersistence'+str(live['scores_total'])+'outcomes/MAE'+str(live['baseline_mae_spaces'])+'spaces is separate and not camera accuracy. Next100-run separate livecheckpoint100;counter92/63sourceIDs/noactivejobs.',
        'Stronger automatic parking-region segmentation still needs suitable qualified ground truth;ACPDS supplied bay polygons are not exhaustive parking-area/background labels. Selected451-file offline demo and dated7pagePDF preserved;physicaloffline/newmachine/manual/student/university acceptance remainopen.'
    ];dump(ROOT/'data/automation_state.json',s)
    inventory=read(ROOT/'data/dataset_inventory.json');inventory.update(inventoried_at=now,acpds_complete_training_acquisition=data,acpds_balanced_head=r)
    for row in inventory['datasets']:
        if row.get('source_id')=='SRC-DS-021':row.update(status='All266development images qualified;one bounded head trial completed;wholeTESTclosed',acquired_development_images=266,train_images_acquired=231,valid_images_acquired=35,remaining_train_images=0,training_acquisition=data,balanced_head=r,used_for_model_training=True,used_for_model_evaluation=True,final_images_or_semantics_opened=False)
        if row.get('source_id')=='SRC-LIVE-001':row.update(snapshot_count=snapshots,raw_path=last['local_path'],provider_timestamp=last.get('provider_timestamp'),latest_prospective_summary=live,prospective_baseline_scored_outcomes=live['scores_total'],prospective_baseline_mae_spaces=live['baseline_mae_spaces'],forecast_target_coverage=live['forecast_coverage'],learned_issuance_metadata=s['singapore_issuance_health'])
    dump(ROOT/'data/dataset_inventory.json',inventory)
    source=ROOT/'data/source_manifest.csv'
    with source.open(encoding='utf-8-sig',newline='') as f:reader=csv.DictReader(f);fields=reader.fieldnames;rows=list(reader)
    assert len(rows)==len({row['source_id'] for row in rows})==63
    for row in rows:
        if row['source_id']=='SRC-DS-021':row.update(used_by=row['used_by']+';'+r['run_id'],modifications=row['modifications']+';all231TRAIN/35VALID acquired with member receipts;frozen-backbone equal-source head fitting',status='One source-adaptation DEVELOPMENT trial completed;gate='+str(r['development_gate_passed'])+';wholeTESTclosed;no production promotion',open_issues=r['scope'])
    with source.open('w',encoding='utf-8',newline='') as f:writer=csv.DictWriter(f,fieldnames=fields);writer.writeheader();writer.writerows(rows)
    new=r['candidate_acpds'];old=r['candidate_pklot'];bnew=r['baseline_acpds'];bold=r['baseline_pklot'];failed=[name for name,passed in r['checks'].items() if not passed]
    metrics=dict(selected_epoch=r['selected_epoch'],epochs_completed=r['epochs_completed'],candidate_checkpoint=r['candidate_checkpoint'],candidate_checkpoint_sha256=r['candidate_checkpoint_sha256'],acpds_baseline_accuracy=bnew['hard']['accuracy_on_covered'],acpds_candidate_accuracy=new['hard']['accuracy_on_covered'],acpds_baseline_false_vacant=bnew['selective']['false_vacant'],acpds_candidate_false_vacant=new['selective']['false_vacant'],acpds_uncertain=new['selective']['uncertain'],pklot_baseline_accuracy=bold['hard']['accuracy_on_covered'],pklot_candidate_accuracy=old['hard']['accuracy_on_covered'],pklot_baseline_false_vacant=bold['selective']['false_vacant'],pklot_candidate_false_vacant=old['selective']['false_vacant'],checks=r['checks'],failed_gates=failed,development_gate_passed=r['development_gate_passed'],per_date_identity_retention=r['per_date_identity_retention'])
    dump(E/'selected_metrics.json',metrics);dump(E/'collection_and_health.json',dict(snapshot_receipt=last,snapshots=snapshots,baseline_scores_added=live['scores_added'],baseline_scores_total=live['scores_total'],baseline_mae_spaces=live['baseline_mae_spaces'],study_issuance=issuance['study_issuance'],health=health,next_collection_after=nexttime))
    title='## 27 October 2026 IST / one bounded source-balanced head trial and complete TRAIN acquisition'
    body=('All 231 ACPDS training images and 35 validation images are now qualified, with 7,842 training and 1,904 validation spaces. Routine resumable acquisition reused 38 receipted members and acquired 228 TRAIN members (295,388,491 new network bytes in 355.386 seconds). No additional experiment count was added for acquisition or individual images. All original bytes, exact range/ETag/CRC checks and provenance remain intact; whole TEST stayed closed. Ten new synthetic tests check receipt identity/hash/role reuse and paired vacancy retention. The full software suite passes 414 tests.\n\n'
          'One prespecified experiment freezes the original ResNet18 backbone and fits its linear head with half the training loss mass from each source. It combines 7,842 ACPDS and 10,104 PKLot training spaces. Validation uses 1,904 ACPDS spaces and 2,028 reused PKLot development spaces, with no consumed camera/date overlap. The fixed selection rule blends per-image ACPDS and per-camera PKLot cross-entropy; epoch zero remains eligible. The trial completed '+str(r['epochs_completed'])+' epochs and selected epoch '+str(r['selected_epoch'])+'. ACPDS hard accuracy changed from '+f"{100*bnew['hard']['accuracy_on_covered']:.4f}"+'% to '+f"{100*new['hard']['accuracy_on_covered']:.4f}"+'%, and confident false vacancies from '+str(bnew['selective']['false_vacant'])+' to '+str(new['selective']['false_vacant'])+' among 831 occupied spaces. PKLot development accuracy changed from '+f"{100*bold['hard']['accuracy_on_covered']:.4f}"+'% to '+f"{100*old['hard']['accuracy_on_covered']:.4f}"+'%, with confident false vacancies '+str(bold['selective']['false_vacant'])+' -> '+str(old['selective']['false_vacant'])+'. Overall development gate: '+str(r['development_gate_passed'])+'. Failed checks: '+(', '.join(failed) if failed else 'none')+'. Exact counts, curves, predictions, per-image/camera results and identity-based per-date retention are preserved. No thresholds, production weights or final cohorts changed.\n\n'
          'Feature extraction and training took '+f"{r['duration_seconds_this_invocation']:.3f}"+' seconds in this invocation, with image checkpoints and saved optimizer/random state. Original ACPDS probabilities reproduced within '+str(r['baseline_probability_max_delta'])+' before fitting; checkpoint state round-trip and unchanged backbone verified. These are development results with supplied polygons; no final, detector-fusion, continuous-camera or automatic-region claim follows. The separate candidate is '+r['candidate_checkpoint']+'. The completed counter increased 91 -> 92 for this one trial; wakeups completed 61, source IDs 63, next 100-run live checkpoint 100, no active jobs.\n\n'
          'The actual 23:40 UTC Singapore observation is snapshot 65. It adds 1,136 rolling persistence outcomes ('+str(live['scores_total'])+' total; MAE '+f"{live['baseline_mae_spaces']:.6f}"+' spaces) and 1,267 baseline forecasts. Another 1,129 genuine learned forecasts were frozen; '+str(health['forecasts_logged'])+' forecasts across '+str(health['global_origins'])+' origins have healthy receipts. Learned targets and matching/error/coverage remain closed until 27 October 10:51 UTC. Next collection after '+nexttime+'. Independent segmentation ground truth, physical/manual/new-machine/student demonstration and university documents remain open. See docs/ACPDS_ADAPTATION_PROTOCOL.md.')
    for name in ['docs/AUTONOMOUS_PROGRESS.md','docs/PROJECT_PROGRESS.md','docs/IMPLEMENTATION_STATUS.md','docs/TEST_RESULTS.md']:append(name,title,body)
    append('docs/SOURCE_REGISTRY.md',title,'SRC-DS-021 original author/MIT/pinned revision remain unchanged. All 266 development JPEGs now have receipted original files and qualified normalized polygons; 27 default-closed TEST names and whole publisher TEST remain unopened. Training/evaluation usage is '+r['run_id']+'. Old PKLot caches are reused development retention data, not fresh final evidence. Candidate and failed gates are preserved without app promotion. 63 unique source IDs.')
    append('docs/ACPDS_ADAPTATION_PROTOCOL.md',title,'Completed trial '+r['run_id']+' selected epoch '+str(r['selected_epoch'])+' of '+str(r['epochs_completed'])+'. Development gate='+str(r['development_gate_passed'])+'. Failed checks: '+(', '.join(failed) if failed else 'none')+'. Full evidence:models/acpds_balanced_head.json. Original checkpoint, all earlier failures and the reserved TEST remain unchanged. A passing training loss alone does not justify a parameter-grid continuation.')
    req=ROOT/'docs/REQUIREMENTS.csv'
    with req.open(encoding='utf-8-sig',newline='') as f:reader=csv.DictReader(f);fields=reader.fieldnames;rows=list(reader)
    for row in rows:
        if row['requirement_id']=='DATA-02':row['actual_evidence']+=';reports/acpds_training_data_latest.json';row['test_result']+=';all266developmentJPEGs/7842TRAIN+1904VALID qualified;TESTclosed'
        if row['requirement_id'] in ('CLS-01','CLS-02'):row['actual_evidence']+=';models/acpds_balanced_head.json;docs/ACPDS_ADAPTATION_PROTOCOL.md';row['test_result']+=';one bounded source-balanced head trial,development gate='+str(r['development_gate_passed'])+',separate checkpoint,original unchanged'
        if row['requirement_id']=='QA-02':row['test_result']+=';414softwaretests,10new receipt/identity-retention fixtures'
    with req.open('w',encoding='utf-8',newline='') as f:writer=csv.DictWriter(f,fieldnames=fields,quoting=csv.QUOTE_ALL);writer.writeheader();writer.writerows(rows)
    dump(E/'checks.json',dict(checked_at=now,counter_before=91,counter_after=92,completed_trial=r['run_id'],acquisition_counted_as_experiment=False,wakeups_completed=61,unique_sources=63,software_tests=414,frozen_hashes_unchanged=frozen,development_gate_passed=r['development_gate_passed'],failed_gates=failed,whole_test_remains_closed=True,active_jobs=[],next100_run_checkpoint=100,next_collection_after=nexttime,full_project_complete=False))
    print(json.dumps(dict(counter=92,tests=414,selected_epoch=r['selected_epoch'],development_gate=r['development_gate_passed'],failed_gates=failed,next_collection=nexttime)))

if __name__=='__main__':main()
